"use client"

import { useId } from "react"
import {
  ChevronDownIcon,
  CircleHelpIcon,
  Settings2Icon,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { Label } from "@/components/ui/label"
import { Switch } from "@/components/ui/switch"
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip"
import { cn } from "@/lib/utils"

export interface DataGridFeatureControl<TFeature extends string = string> {
  id: TFeature
  label: string
  checked: boolean
}

export interface DataGridFeatureControlsProps<TFeature extends string = string> {
  features: readonly DataGridFeatureControl<TFeature>[]
  onFeatureChange: (feature: TFeature, checked: boolean) => void
  label?: string
  helpText?: string
  className?: string
}

export function DataGridFeatureControls<TFeature extends string = string>({
  features,
  onFeatureChange,
  label = "Table features",
  helpText = "Enable or disable features to customize the table.",
  className,
}: DataGridFeatureControlsProps<TFeature>) {
  const instanceId = useId()

  return (
    <div className={cn("flex items-center gap-1.5", className)}>
      <DropdownMenu>
        <DropdownMenuTrigger
          render={
            <Button variant="outline" size="sm">
              <Settings2Icon aria-hidden="true" />
              {label}
              <ChevronDownIcon aria-hidden="true" />
            </Button>
          }
        />
        <DropdownMenuContent align="start" className="w-64">
          <DropdownMenuGroup>
            <DropdownMenuLabel>{label}</DropdownMenuLabel>
            <div className="space-y-0.5">
              {features.map((feature) => {
                const id = `${instanceId}-${feature.id}`

                return (
                  <Label
                    key={feature.id}
                    htmlFor={id}
                    className="w-full cursor-pointer justify-between gap-4 rounded-md px-2 py-1.5 text-sm font-normal hover:bg-accent"
                  >
                    {feature.label}
                    <Switch
                      id={id}
                      checked={feature.checked}
                      onCheckedChange={(checked) => onFeatureChange(feature.id, checked)}
                    />
                  </Label>
                )
              })}
            </div>
          </DropdownMenuGroup>
        </DropdownMenuContent>
      </DropdownMenu>
      <TooltipProvider>
        <Tooltip>
          <TooltipTrigger
            render={
              <Button variant="ghost" size="icon-sm" aria-label={`About ${label.toLowerCase()}`}>
                <CircleHelpIcon aria-hidden="true" />
              </Button>
            }
          />
          <TooltipContent>{helpText}</TooltipContent>
        </Tooltip>
      </TooltipProvider>
    </div>
  )
}
